// The engine guide on the Configuration page: what the engine can do, the impact it can show, how far it scales and
// what is still missing, as the engine states it (GET /api/m2c/guide). This page renders that document and the
// engine's live status; it adds nothing of its own.
const e=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const INT=new Intl.NumberFormat('en-CA',{maximumFractionDigits:0});
const group=(id,title,count,body)=>`<details class="schema-group guide-group" data-group="${e(id)}" open><summary class="schema-group-head"><h3>${e(title)}</h3>${count!=null?`<span class="schema-count">${e(count)}</span>`:''}</summary><div class="guide-body">${body}</div></details>`;
const chips=list=>`<span class="guide-chips">${(list||[]).map(w=>`<span class="guide-chip">${e(w)}</span>`).join('')}</span>`;
// The guide as the Configuration page shows it: one card per section, each a schema-group so the sidebar lists it.
export function guideMarkup(g){if(!g)return '';const st=g.status||{},lim=st.limits||{},sc=g.scale||{};
 const caps=`<div class="guide-grid">${(g.capabilities||[]).map(c=>`<article class="guide-card"><h4>${e(c.title)}</h4><p>${e(c.text)}</p><p class="guide-where">${chips(c.where)}</p></article>`).join('')}</div>`;
 const impacts=`<table class="guide-table"><thead><tr><th>Impact</th><th>What you see</th><th>Where</th></tr></thead><tbody>${(g.impacts||[]).map(i=>`<tr><td><strong>${e(i.title)}</strong></td><td>${e(i.text)}</td><td class="guide-muted">${e(i.where)}</td></tr>`).join('')}</tbody></table>`;
 const measured=`<table class="guide-table guide-num"><thead><tr><th>Town</th><th>Homes</th><th>Accounts</th><th>Registers</th><th>Generate</th><th>Replay a year</th><th>Memory</th></tr></thead><tbody>${(sc.measured||[]).map(m=>`<tr><td>${e(m.town)}</td><td>${INT.format(m.homes)}</td><td>${INT.format(m.accounts)}</td><td>${INT.format(m.registers)}</td><td>${e(m.generateS)} s</td><td>${e(m.replayS)} s</td><td>${m.memoryMB?INT.format(m.memoryMB)+' MB':'—'}</td></tr>`).join('')}</tbody></table><p class="small-note">Measured ${e(sc.measuredOn||'')}.</p>`;
 const limits=`<dl class="guide-dl">${(sc.limits||[]).map(l=>`<dt>${e(l.title)}</dt><dd>${e(l.text)}</dd>`).join('')}</dl>`;
 const reqs=`<p class="guide-where">${chips([`${lim.scenarios??'—'} scenarios`,`${lim.tables??'—'} tables`,`${lim.episodes??'—'} episodes per run`,`${INT.format(lim.actions||0)} actions per run`,`${lim.interruptions??'—'} interruptions per run`,`${lim.pageRows??'—'} rows a page`,`${INT.format(lim.csvRows||0)} rows a CSV page`,`${lim.yearDays??'—'} run days`])}</p>`;
 const gaps=`<ol class="guide-gaps">${(g.gaps||[]).map(x=>`<li><strong>${e(x.title)}.</strong> ${e(x.text)} <span class="guide-plan">Next: ${e(x.plan)}</span></li>`).join('')}</ol>`;
 const status=`<dl class="guide-status"><dt>Engine</dt><dd>${e(st.engine||'—')}</dd><dt>Generator</dt><dd>${e(st.generatorVersion||'—')}</dd><dt>Snapshot schema</dt><dd>${e(st.schemaVersion||'—')}</dd><dt>Towns</dt><dd>${(st.towns||[]).length?chips(st.towns):'—'}</dd><dt>Generates towns</dt><dd>${st.capabilities?.generate?'Yes':'No (prebuilt towns only)'}</dd></dl>`;
 return `<p class="guide-summary">${e(g.summary)}</p>`+group('capabilities','What it can do',(g.capabilities||[]).length,caps)+group('impacts','The impact it can show',(g.impacts||[]).length,impacts)+group('scale','How far it scales',null,measured+limits+reqs)+group('gaps','Gaps still remaining',(g.gaps||[]).length,gaps)+group('status','This engine',null,status);}
// Fetches the guide once per engine and renders it; without an engine the page keeps its note.
export function installGuide({api,root=document.getElementById('engine-guide'),fetchImpl}){let cache=null,base=null,busy=null;const f=fetchImpl||globalThis.fetch?.bind(globalThis);
 async function render(){if(!root)return null;const url=(typeof api==='function'?api():api)+'/m2c/guide';if(cache&&base===url){root.innerHTML=guideMarkup(cache);return cache;}if(busy&&base===url)return busy;base=url;
  busy=(async()=>{try{const r=await f(url);if(!r.ok)throw Error('Engine '+r.status);cache=await r.json();root.innerHTML=guideMarkup(cache);return cache;}catch(err){cache=null;root.innerHTML=`<p class="small-note">The engine's guide is not available${/Engine 40[45]/.test(err.message)?' on this engine yet':''}. Connect an engine (the hosted site, or <code>uv run utilsim serve</code> with <code>?engine=http://127.0.0.1:8010</code>) to read it.</p>`;return null;}finally{busy=null;}})();return busy;}
 return {render,refresh:()=>{cache=null;return render();},get guide(){return cache;}};}
